CREATE TABLE IF NOT EXISTS customers(id BIGSERIAL PRIMARY KEY,customer_date DATE NOT NULL,race VARCHAR(30) NOT NULL CHECK(race IN ('Black','White','Indian','Asian','Arabic')),gender VARCHAR(20) NOT NULL CHECK(gender IN ('Male','Female')),location VARCHAR(20) NOT NULL CHECK(location IN ('Local','Foreign')),age_group VARCHAR(20) NOT NULL CHECK(age_group IN ('30s','40s','50s','60s','over')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS customers_date_idx ON customers(customer_date);